        {"kind": "metric", "sql": "SELECT metric, count(*) n, min(value) mn, max(value) mx FROM normal_metrics WHERE attr_k8s_pod_name LIKE 'attractions%' AND metric IN ('k8s.container.ready','k8s.container.restarts') GROUP BY metric ORDER BY metric", "claim": "In the normal period the attractions pod is ready (1) with zero restarts."},
        {"kind": "trace", "sql": "SELECT 'normal' p, count(*) n FROM normal_traces WHERE service_name='attractions' UNION ALL SELECT 'abnormal' p, count(*) n FROM abnormal_traces WHERE service_name='attractions'", "claim": "The attractions service emits about 104 spans in the normal period and none in the incident period."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 med_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE 'attractions.%' GROUP BY 1,2 ORDER BY 1,2", "claim": "Frontend's calls to attractions (NearbyCinema, NearbyMus, NearbyRest) all return Error status during the incident, about 490 calls in total."}
      ]
    }
  ],
  "propagation": [
    {"from": "attractions", "to": "frontend", "evidence": [
      {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE 'HTTP /%' GROUP BY 1,2 ORDER BY 1,2", "claim": "Frontend's /cinema, /museums and /restaurants routes return HTTP 500 for about 490 requests, while other routes stay 200."},
      {"kind": "log", "sql": "SELECT message, count(*) n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY 1 ORDER BY 2 DESC", "claim": "Frontend logs ERROR lines 'NearbyCinema/NearbyMus/NearbyRest failed for hotelId N', matching the attractions call failures."}
    ]}
  ]
}
